#!/usr/bin/env python3
"""Writes src/font.s: 3x5 status font, each pixel doubled horizontally (6 px, white on color screens).
Glyph order: 0-9, C D E H I P R, blank, S O A T L V (indices 18-23), power-up icons 24 shield, 25 cool (snowflake), 26 spread."""
G="""111 101 101 101 111|010 110 010 010 111|111 001 111 100 111|111 001 111 001 111|101 101 111 001 001|111 100 111 001 111|111 100 111 101 111|111 001 001 001 001|111 101 111 101 111|111 101 111 001 111|111 100 100 100 111|110 101 101 101 110|111 100 110 100 111|101 101 111 101 101|111 010 010 010 111|111 101 111 100 100|110 101 110 101 101|000 000 000 000 000|011 100 010 001 110|010 101 101 101 010|010 101 111 101 101|111 010 010 010 010|100 100 100 100 111|101 101 101 101 010|111 111 111 111 010|101 010 111 010 101|101 111 010 010 010"""
out=['; generated by tools/gen_font.py - glyphs 0-9,C,D,E,H,I,P,R,blank,S,O,A,T,L,V,shield,cool,spread; 5 rows each','        .segment "RODATA"','font:']
for g in G.split('|'):
    rows=[sum(3<<(2*j) for j,c in enumerate(r) if c=='1') for r in g.split()]
    out.append('        .byte '+','.join('$%02X'%b for b in rows))
open(__import__('os').path.dirname(__file__)+'/../src/font.s','w').write('\n'.join(out)+'\n')
